<?php else: ?><div class="project-grid"><?php foreach($projects as $project): ?><article class="project-card" <?= isset($project['id'])?'id="project-'.e($project['id']).'"':'' ?>><span class="badge"><?= e($project['status']) ?></span><h2><?= e($project['name']) ?></h2><p><?= nl2br(e($project['description'])) ?></p><ul class="feature-tags"><?php foreach($project['technologies'] as $technology): ?><li><?= e($technology) ?></li><?php endforeach ?></ul><div class="button-row">
<?php if($url=safe_url($project['github_url']??null)): ?><a class="button secondary" href="<?= e($url) ?>" rel="noopener noreferrer">GitHub <?= icon('diagonal') ?></a><?php endif ?>
<?php if($url=safe_url($project['github_release_url']??null)): ?><a class="text-link" href="<?= e($url) ?>">GitHub release <?= e($project['github_release_tag']) ?> <?= icon('diagonal') ?></a><?php endif ?>
<?php foreach($project['files']??[] as $file): ?><a class="text-link" href="/projects/download/<?= e($file['id']) ?>"><?= $file['kind']==='source'?'Source ZIP':'Release' ?> <?= e($file['version']) ?> · <?= e($file['filename']) ?> (<?= number_format($file['size']/1048576,1) ?> MB) ↓</a><?php endforeach ?></div>
<?php if(!empty($project['synced_at'])): ?><p class="quiet">GitHub: <?= (int)$project['github_stars'] ?> stars · synced <?= gmdate('Y-m-d',$project['synced_at']) ?></p><?php endif ?></article><?php endforeach ?></div><?php endif ?></section>
